            | Pattern::CssPseudoElements
            | Pattern::CssFunctionalPseudoClassesAt0
            | Pattern::CssFunctionalPseudoClassesAt1
            | Pattern::CssFunctionalPseudoClassesAt2
            | Pattern::CssFunctionalPseudoClassesAt3
            | Pattern::AtRuleMediaAt0At4At1
